<script setup>
import{router,useForm}from'@inertiajs/vue3';defineProps({plans:Array});const form=useForm({name:'',installment_count:2,schedule_mode:'evenly_spaced',adjustment_direction:'fee',adjustment_mode:'fixed',adjustment_value:0});const submit=()=>form.post('/admin/plans-paiement',{preserveScroll:true,onSuccess:()=>form.reset()});const remove=p=>confirm(`Supprimer « ${p.name} » ?`)&&router.delete(`/admin/plans-paiement/${p.id}`,{preserveScroll:true});
</script>
<template><section class="grid gap-6 lg:grid-cols-[.65fr_1.35fr]"><div class="rounded-3xl bg-white p-6"><p class="text-xs font-bold uppercase tracking-wider text-coral">Nouvel échéancier</p><h2 class="mt-2 font-serif text-3xl">Plan de paiement</h2><form @submit.prevent="submit" class="mt-6 space-y-4"><input v-model="form.name" class="w-full rounded-xl border border-black/10 px-4 py-3" placeholder="Paiement en 3 fois"/><input v-model="form.installment_count" type="number" min="2" max="24" class="w-full rounded-xl border border-black/10 px-4 py-3"/><select v-model="form.schedule_mode" class="w-full rounded-xl border border-black/10 bg-white px-4 py-3"><option value="evenly_spaced">Répartition équivalente</option><option value="monthly_end">Chaque fin de mois</option></select><div class="grid grid-cols-2 gap-2"><select v-model="form.adjustment_direction" class="rounded-xl border bg-white px-3 py-3"><option value="fee">Frais</option><option value="discount">Remise</option></select><select v-model="form.adjustment_mode" class="rounded-xl border bg-white px-3 py-3"><option value="fixed">CHF</option><option value="percentage">%</option></select></div><input v-model="form.adjustment_value" type="number" min="0" step=".01" class="w-full rounded-xl border px-4 py-3"/><p v-if="Object.keys(form.errors).length" class="text-xs text-red-600">{{Object.values(form.errors)[0]}}</p><button class="w-full rounded-full bg-ink py-3.5 font-bold text-white">Créer le plan</button></form></div><div class="overflow-hidden rounded-3xl bg-white"><div class="border-b border-black/5 px-6 py-5"><h2 class="font-serif text-2xl">Plans proposés</h2><p class="mt-1 text-xs text-black/45">{{plans.length}} plans configurés</p></div><div class="overflow-x-auto"><table class="w-full min-w-[720px] text-left"><thead class="bg-[#f7f5f0] text-[11px] font-bold uppercase tracking-wider text-black/45"><tr><th class="px-6 py-4">Plan</th><th class="px-5 py-4">Échéances</th><th class="px-5 py-4">Calendrier</th><th class="px-5 py-4">Ajustement</th><th class="px-6 py-4 text-right">Actions</th></tr></thead><tbody class="divide-y divide-black/5"><tr v-for="p in plans" :key="p.id"><td class="px-6 py-5 font-bold">{{p.name}}</td><td class="px-5 py-5">{{p.installment_count}} factures</td><td class="px-5 py-5 text-sm">{{p.schedule_mode==='monthly_end'?'Chaque fin de mois':'Répartition équivalente'}}</td><td class="px-5 py-5" :class="p.adjustment_direction==='fee'?'text-amber-700':'text-green-700'">{{p.adjustment_direction==='fee'?'+':'−'}}{{Number(p.adjustment_value)}}{{p.adjustment_mode==='percentage'?' %':' CHF'}}</td><td class="px-6 py-5 text-right"><button @click="remove(p)" class="grid h-9 w-9 place-items-center rounded-full bg-red-50 text-red-500 ml-auto">×</button></td></tr></tbody></table><p v-if="!plans.length" class="p-16 text-center text-black/40">Aucun plan.</p></div></div></section></template>
